      "text-diff": {
        "ui": {
          "r62_0": "Dán văn bản gốc vào đây",
          "r62_1": "Dán văn bản đã sửa vào đây",
          "r62_2": "So sánh hai văn bản và làm nổi bật khác biệt",
          "r62_3": "Văn bản gốc",
          "r62_4": "Văn bản đã sửa",
          "r62_5": "Kết quả unified diff",
          "r62_6": "Bỏ qua khoảng trắng",
          "r62_7": "Bỏ qua chữ hoa/thường",
          "r62_8": "so sánh từng từ và khoảng trắng giữa chúng, nên khi sửa một từ trong đoạn dài chỉ từ đó được hiển thị thay vì cả dòng. Phù hợp cho văn xuôi và prompt.",
          "r62_9": "so sánh từng ký tự (theo điểm mã Unicode, nên emoji và chữ có dấu được tính là một). Phù hợp cho chuỗi ngắn như ID, hash hoặc URL.",
          "r6_0": "<span class=\"w-3 h-3 bg-success-100 border border-success-300 rounded-sm\"></span> Đã thêm",
          "r6_1": "<span class=\"w-3 h-3 bg-error-100 border border-error-300 rounded-sm\"></span> Đã xóa",
          "r6_2": "Đã thêm",
          "r6_3": "Đã xóa",
          "r6_4": "Không đổi",
          "r6_5": "<span class=\"material-symbols-rounded\" aria-hidden=\"true\" data-icon=\"content_copy\"></span> Sao chép diff",
          "r6_6": "<span class=\"material-symbols-rounded\" aria-hidden=\"true\" data-icon=\"download\"></span> Tải xuống .diff",
          "r6_7": "Diff dùng thuật toán Myers để tìm kịch bản chỉnh sửa ngắn nhất: số lần chèn và xóa ít nhất để biến văn bản gốc thành văn bản đã sửa. Mọi phần khác được hiển thị là không đổi. Tất cả chạy trong trình duyệt của bạn. Với dữ liệu rất lớn và ít phần chung, việc tìm kiếm bị giới hạn để trang luôn phản hồi; trang sẽ báo khi điều đó xảy ra, và diff hiển thị vẫn đúng nhưng có thể không phải nhỏ nhất.",
          "r6_8": "<strong>Dòng</strong> so sánh toàn bộ dòng, giống <code>diff</code> và <code>git diff</code>. Phù hợp cho mã nguồn, tệp cấu hình và log.",
          "r6_9": "<strong>Bỏ qua chữ hoa/thường</strong> coi chữ hoa và chữ thường là như nhau.",
          "r6_10": "Ở chế độ dòng, <strong>bỏ qua khoảng trắng</strong> xóa mọi dấu cách, tab và khoảng trắng khác trước khi so sánh hai dòng, giống <code>git diff -w</code>, nên các dòng chỉ thụt lề lại được coi là không đổi. Ở chế độ từ và ký tự, mọi chuỗi khoảng trắng khớp với nhau, nên <code>a&nbsp;&nbsp;b</code> khớp với <code>a b</code>, nhưng khoảng trắng thêm vào chỗ trước đó không có vẫn được tính là thay đổi.",
          "r6_11": "Bản xuất dùng định dạng unified do <code>diff -u</code> tạo và <code>patch</code> đọc:",
          "r6_12": "<code>---</code> và <code>+++</code> đặt tên tệp gốc và tệp đã sửa.",
          "r6_13": "Mỗi hunk bắt đầu bằng <code>@@ -start,count +start,count @@</code>: số dòng đầu tiên và số dòng mà hunk bao phủ trong mỗi tệp. count bằng 1 sẽ được lược bỏ.",
          "r6_14": "Dòng bắt đầu bằng dấu cách là ngữ cảnh, dòng <code>-</code> bị xóa và dòng <code>+</code> được thêm. Mỗi hunk có tối đa 3 dòng ngữ cảnh, và các thay đổi gần nhau dùng chung một hunk.",
          "r6_15": "<code>\\ No newline at end of file</code> đánh dấu dòng cuối không có ký tự xuống dòng.",
          "r6_16": "Để áp dụng tệp đã tải: <code>patch original.txt text-diff.diff</code>.",
          "r6_17": "Khi bật tùy chọn bỏ qua, các dòng được coi là giống nhau sẽ được ghi làm ngữ cảnh từ văn bản gốc. Áp dụng bản vá đó không tái tạo các khác biệt đã bị bỏ qua.",
          "r6_18": "<strong>Tệp cấu hình:</strong> so sánh <code>.env</code>, YAML hoặc cấu hình nginx đã triển khai với phiên bản bạn mong đợi, và bật bỏ qua khoảng trắng để ẩn khác biệt thụt lề.",
          "r6_19": "<strong>Phiên bản prompt LLM:</strong> dùng chế độ từ để thấy chính xác chỉ dẫn nào đã thay đổi giữa hai bản nháp prompt trước khi so sánh đầu ra của mô hình.",
          "r6_20": "<strong>Review mã:</strong> dán hai phiên bản của một hàm để đọc thay đổi bên ngoài trình soạn thảo, hoặc xuất <code>.diff</code> để đính kèm vào issue hay tin nhắn."
        }
      },
